-- PostgreSQL source-of-truth schema. IDs remain TEXT for compatibility with existing SQLite IDs and API payloads.
CREATE TABLE users (id text PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, full_name text NOT NULL, role text NOT NULL DEFAULT 'CUSTOMER', active boolean NOT NULL DEFAULT true, warehouse_id text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE password_resets (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL, expires_at timestamptz NOT NULL, used_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_profiles (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, phone text, comm_prefs jsonb NOT NULL DEFAULT '{}'::jsonb, notif_prefs jsonb NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE categories (id text PRIMARY KEY, name text UNIQUE NOT NULL, description text, sort_order integer NOT NULL DEFAULT 0, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE products (id text PRIMARY KEY, sku text UNIQUE NOT NULL, name text NOT NULL, description text NOT NULL DEFAULT '', details text NOT NULL DEFAULT '', price_paise integer NOT NULL DEFAULT 0 CHECK(price_paise>=0), image_url text NOT NULL DEFAULT '', stock integer NOT NULL DEFAULT 0 CHECK(stock>=0), active boolean NOT NULL DEFAULT true, category_id text REFERENCES categories(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE addresses (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, label text, full_name text NOT NULL, line1 text NOT NULL, line2 text, city text NOT NULL, state text NOT NULL, postal_code text NOT NULL, country text NOT NULL DEFAULT 'IN', phone text, is_default boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (id text PRIMARY KEY, order_number text UNIQUE NOT NULL, customer_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, status text NOT NULL, subtotal_paise integer NOT NULL DEFAULT 0 CHECK(subtotal_paise>=0), shipping_paise integer NOT NULL DEFAULT 0 CHECK(shipping_paise>=0), discount_paise integer NOT NULL DEFAULT 0 CHECK(discount_paise>=0), credit_used_paise integer NOT NULL DEFAULT 0 CHECK(credit_used_paise>=0), shipping_address text, payment_status text NOT NULL DEFAULT 'UNPAID', payment_method text, carrier text, tracking_number text, kind text NOT NULL DEFAULT 'STANDARD', source_return_id text, estimated_delivery text, created_at timestamptz NOT NULL DEFAULT now(), delivered_at timestamptz);
CREATE TABLE order_items (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, product_id text NOT NULL REFERENCES products(id), sku text NOT NULL, product_name text NOT NULL, product_image_url text, quantity integer NOT NULL CHECK(quantity>=1), unit_price_paise integer NOT NULL CHECK(unit_price_paise>=0), line_total_paise integer NOT NULL CHECK(line_total_paise>=0));
CREATE TABLE order_events (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, status text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cart_items (user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id text NOT NULL REFERENCES products(id) ON DELETE CASCADE, quantity integer NOT NULL CHECK(quantity>=1), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(user_id,product_id));
CREATE TABLE return_reasons (code text PRIMARY KEY, label text NOT NULL, description text, active boolean NOT NULL DEFAULT true, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE returns (id text PRIMARY KEY, return_number text UNIQUE NOT NULL, order_id text NOT NULL REFERENCES orders(id), customer_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, status text NOT NULL, resolution_type text, description text, approved_at timestamptz, approved_by text REFERENCES users(id), cancelled_at timestamptz, cancel_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE orders ADD CONSTRAINT orders_source_return_fk FOREIGN KEY(source_return_id) REFERENCES returns(id);
CREATE TABLE return_items (id text PRIMARY KEY, return_id text NOT NULL REFERENCES returns(id) ON DELETE CASCADE, order_item_id text NOT NULL REFERENCES order_items(id), quantity integer NOT NULL CHECK(quantity>=1), reason_code text NOT NULL REFERENCES return_reasons(code), description text);
CREATE TABLE return_events (id text PRIMARY KEY, return_id text NOT NULL REFERENCES returns(id) ON DELETE CASCADE, status text NOT NULL, description text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pickups (id text PRIMARY KEY, return_id text UNIQUE NOT NULL REFERENCES returns(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN('PICKUP','DROP_OFF')), address text, date text, time_window text, carrier text, tracking_number text, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds (id text PRIMARY KEY, return_id text UNIQUE NOT NULL REFERENCES returns(id) ON DELETE CASCADE, kind text NOT NULL CHECK(kind IN('REFUND','REPLACEMENT','EXCHANGE','STORE_CREDIT')), amount_paise integer NOT NULL DEFAULT 0, method text, status text NOT NULL, initiated_at timestamptz, completed_at timestamptz);
CREATE TABLE store_credit_ledger (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, type text NOT NULL CHECK(type IN('CREDIT','DEBIT','ADJUSTMENT')), amount_paise integer NOT NULL, reason text, reference_type text NOT NULL, reference_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(reference_type,reference_id));
CREATE TABLE idempotency_keys (key text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, order_id text NOT NULL REFERENCES orders(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, return_id text REFERENCES returns(id) ON DELETE CASCADE, type text NOT NULL, title text NOT NULL, body text NOT NULL, is_read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE documents (id text PRIMARY KEY, return_id text NOT NULL REFERENCES returns(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, kind text NOT NULL, filename text NOT NULL, mime text NOT NULL, size bigint NOT NULL, storage_path text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_tickets (id text PRIMARY KEY, ticket_number text UNIQUE NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, return_id text REFERENCES returns(id) ON DELETE SET NULL, subject text NOT NULL, status text NOT NULL DEFAULT 'OPEN', priority text NOT NULL DEFAULT 'NORMAL', assigned_to text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_messages (id text PRIMARY KEY, ticket_id text NOT NULL REFERENCES support_tickets(id) ON DELETE CASCADE, author_role text NOT NULL CHECK(author_role IN('CUSTOMER','ADMIN','SYSTEM')), body text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE feedback (id text PRIMARY KEY, return_id text UNIQUE NOT NULL REFERENCES returns(id) ON DELETE CASCADE, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, rating integer NOT NULL CHECK(rating BETWEEN 1 AND 5), comment text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE warehouses (id text PRIMARY KEY, code text UNIQUE NOT NULL, name text NOT NULL, city text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE users ADD CONSTRAINT users_warehouse_fk FOREIGN KEY(warehouse_id) REFERENCES warehouses(id);
CREATE TABLE warehouse_locations (id text PRIMARY KEY, warehouse_id text NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE, code text NOT NULL, name text NOT NULL, kind text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(warehouse_id,code));
CREATE TABLE receiving_records (id text PRIMARY KEY, return_id text UNIQUE NOT NULL REFERENCES returns(id) ON DELETE CASCADE, warehouse_id text NOT NULL REFERENCES warehouses(id), location_id text REFERENCES warehouse_locations(id), received_by text NOT NULL REFERENCES users(id), tracking_number text, carrier text, package_condition text NOT NULL, discrepancy text NOT NULL DEFAULT 'NONE', expected_quantity integer NOT NULL CHECK(expected_quantity>=0), received_quantity integer NOT NULL CHECK(received_quantity>=0), notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inspections (id text PRIMARY KEY, return_id text UNIQUE NOT NULL REFERENCES returns(id) ON DELETE CASCADE, warehouse_id text NOT NULL REFERENCES warehouses(id), inspected_by text NOT NULL REFERENCES users(id), result text, notes text, started_at timestamptz NOT NULL DEFAULT now(), completed_at timestamptz);
CREATE TABLE inspection_items (id text PRIMARY KEY, inspection_id text NOT NULL REFERENCES inspections(id) ON DELETE CASCADE, return_item_id text NOT NULL REFERENCES return_items(id) ON DELETE CASCADE, result text NOT NULL, product_condition text NOT NULL, packaging_condition text NOT NULL, missing_components text, damage_notes text, serial_number text, quantity integer NOT NULL CHECK(quantity>=1), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(inspection_id,return_item_id));
CREATE TABLE dispositions (id text PRIMARY KEY, return_item_id text UNIQUE NOT NULL REFERENCES return_items(id) ON DELETE CASCADE, return_id text NOT NULL REFERENCES returns(id) ON DELETE CASCADE, inspection_id text NOT NULL REFERENCES inspections(id) ON DELETE CASCADE, warehouse_id text NOT NULL REFERENCES warehouses(id), location_id text REFERENCES warehouse_locations(id), action text NOT NULL, quantity integer NOT NULL CHECK(quantity>=1), reason text, notes text, recovery_value_paise integer NOT NULL DEFAULT 0 CHECK(recovery_value_paise>=0), operator_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE inventory_buckets (warehouse_id text NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE, product_id text NOT NULL REFERENCES products(id) ON DELETE CASCADE, state text NOT NULL, quantity integer NOT NULL DEFAULT 0 CHECK(quantity>=0), location_id text REFERENCES warehouse_locations(id), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(warehouse_id,product_id,state));
CREATE TABLE inventory_movements (id text PRIMARY KEY, warehouse_id text NOT NULL REFERENCES warehouses(id), product_id text NOT NULL REFERENCES products(id), sku text NOT NULL, quantity integer NOT NULL CHECK(quantity>0), from_state text, to_state text, from_location_id text REFERENCES warehouse_locations(id), to_location_id text REFERENCES warehouse_locations(id), reason text NOT NULL, reference_type text NOT NULL, reference_id text NOT NULL, operator_id text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(reference_type,reference_id,reason,product_id));
CREATE TABLE warehouse_tasks (id text PRIMARY KEY, warehouse_id text NOT NULL REFERENCES warehouses(id) ON DELETE CASCADE, kind text NOT NULL, title text NOT NULL, return_id text REFERENCES returns(id) ON DELETE CASCADE, order_id text REFERENCES orders(id) ON DELETE CASCADE, priority text NOT NULL DEFAULT 'NORMAL', status text NOT NULL DEFAULT 'TODO', assigned_to text REFERENCES users(id), blocked_reason text, created_at timestamptz NOT NULL DEFAULT now(), due_at timestamptz NOT NULL, started_at timestamptz, completed_at timestamptz);
CREATE TABLE audit_log (id text PRIMARY KEY, actor_id text REFERENCES users(id), actor_role text NOT NULL, warehouse_id text REFERENCES warehouses(id), action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, previous_state jsonb, new_state jsonb, metadata jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_audit_log (id text PRIMARY KEY, actor_id text REFERENCES users(id), actor_role text NOT NULL, action text NOT NULL, entity_type text NOT NULL, entity_id text NOT NULL, previous_state jsonb, new_state jsonb, metadata jsonb, ip text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE settings (key text PRIMARY KEY, value jsonb NOT NULL, updated_by text REFERENCES users(id), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notification_templates (key text PRIMARY KEY, title text NOT NULL, body text NOT NULL, active boolean NOT NULL DEFAULT true, updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX idx_orders_customer ON orders(customer_id); CREATE INDEX idx_returns_customer ON returns(customer_id); CREATE INDEX idx_returns_order ON returns(order_id); CREATE INDEX idx_order_items_order ON order_items(order_id); CREATE INDEX idx_ledger_user_created ON store_credit_ledger(user_id,created_at); CREATE INDEX idx_tasks_site_status ON warehouse_tasks(warehouse_id,status,due_at); CREATE INDEX idx_movements_product ON inventory_movements(product_id,created_at);
